// the search index, generated by the site: psyche only searches it
export const url = "/search.json";

type Page = { url: string; title?: string; content?: unknown; section?: string; date?: Date };

const text = (content: unknown) =>
  String(content ?? "")
    .replace(/<[^>]+>/g, " ")
    .replace(/[#*_`>]/g, "");

export default function ({ search }: { search: { pages: (query: string) => Page[] } }) {
  return JSON.stringify(
    search.pages("url^=/").flatMap((page) =>
      page.url === url || !page.title
        ? []
        : [
            {
              href: page.url,
              title: page.title,
              body: text(page.content),
              section: page.section,
            },
          ],
    ),
  );
}
